"use strict";var should=require("should"),tokens=require("./"),re=/<%=\s*[^>]+%>/g,pretty=function(e){return require("js-beautify").html(e,{indent_char:" ",indent_size:2})};describe("preserve tokens",function(){var e=/__ID.{5}__\n__ID.{5}__\n__ID.{5}__/,n=/<%=\s*[^>]+%>/g;it("should (e.g. shouldn't, but will) mangle tokens in the given string",function(){pretty("<ul><li><%= name %></li></ul>").should.equal("<ul>\n  <li>\n    <%=n ame %>\n  </li>\n</ul>")}),it("should preserve tokens in the given string",function(){tokens.after(pretty(tokens.before("<ul><li><%= name %></li></ul>",n))).should.equal("<ul>\n  <li><%= name %></li>\n</ul>")}),describe(".before()",function(){it("should replace matches with placeholder tokens:",function(){tokens.before("<%= a %>\n<%= b %>\n<%= c %>",n).should.match(e)})}),describe("tokens.after()",function(){it("should replace placeholder tokens with original values:",function(){var t=tokens.before("<%= a %>\n<%= b %>\n<%= c %>",n);t.should.match(e),tokens.after(t).should.equal("<%= a %>\n<%= b %>\n<%= c %>")})})});